<?php require __DIR__ . '/_shared.php';
$stmt=$pdo->prepare("SELECT COALESCE(SUM(amount),0) total,COALESCE(SUM(CASE WHEN status='available' THEN amount ELSE 0 END),0) available,COALESCE(SUM(CASE WHEN status='paid' THEN amount ELSE 0 END),0) paid,COALESCE(SUM(CASE WHEN status='pending' THEN amount ELSE 0 END),0) pending FROM affiliate_rewards WHERE affiliate_id=?");$stmt->execute([$affiliateId]);$sum=$stmt->fetch(PDO::FETCH_ASSOC)?:[];
$stmt=$pdo->prepare("SELECT ar.amount,ar.status,ar.reference,ar.created_at,ar.paid_at,u.name referred_name FROM affiliate_rewards ar JOIN affiliate_referrals r ON r.id=ar.referral_id JOIN users u ON u.id=r.referred_user_id WHERE ar.affiliate_id=? ORDER BY ar.created_at DESC LIMIT 100");$stmt->execute([$affiliateId]);$rows=$stmt->fetchAll(PDO::FETCH_ASSOC);
aff_head('Commissions','commissions'); ?>
